def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    for r in range(h - 1):
        for c in range(w):
            color = grid[r][c]
            if color == background:
                continue
            for dc in (-1, 1):
                c2 = c + dc
                if not (0 <= c2 < w and grid[r + 1][c2] == color):
                    continue
                # Extend this diagonal in both directions until the edge or an obstacle.
                for dr, step_c, rr, cc in ((-1, -dc, r - 1, c - dc), (1, dc, r + 2, c2 + dc)):
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == background:
                        out[rr][cc] = color
                        rr += dr
                        cc += step_c
    return out

